"""Parse the nightly orders export (pipe-separated) into records."""

import csv
import logging
from pathlib import Path

log = logging.getLogger(__name__)

FIELDS = ("id", "region", "amount_cents", "tags")


def parse(line):
    parts = line.strip().split("|")
    record_id = parts[0]
    region = parts[1].lower()
    amount_cents = int(parts[2])
    tags = [tag for tag in parts[3].split(",") if tag]
    return {"id": record_id, "region": region, "amount_cents": amount_cents, "tags": tags}


def load(path):
    records = []
    with Path(path).open(encoding="utf-8") as handle:
        for number, line in enumerate(handle, start=1):
            try:
                record = parse(line)
            except (IndexError, ValueError) as error:
                log.warning("skipping line %d: %s", number, error)
                continue
            if record is not None:
                records.append(record)
    return records


def totals_by_region(records):
    totals = {}
    for record in records:
        totals[record["region"]] = totals.get(record["region"], 0) + record["amount_cents"]
    return totals


def write_summary(records, out_path):
    totals = totals_by_region(records)
    with Path(out_path).open("w", newline="", encoding="utf-8") as handle:
        writer = csv.writer(handle)
        writer.writerow(["region", "amount_cents"])
        for region in sorted(totals):
            writer.writerow([region, totals[region]])


if __name__ == "__main__":
    import sys

    write_summary(load(sys.argv[1]), sys.argv[2])
